CREATE TABLE "BookChapter" ("id" TEXT NOT NULL,"bookId" TEXT NOT NULL,"chapterNumber" INTEGER NOT NULL,"title" TEXT NOT NULL,"slug" TEXT NOT NULL,"startPage" INTEGER,"endPage" INTEGER,"extractedText" TEXT,"reviewedText" TEXT,"summary" TEXT,"keywords" TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[],"approved" BOOLEAN NOT NULL DEFAULT false,"sortOrder" INTEGER NOT NULL DEFAULT 0,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "BookChapter_pkey" PRIMARY KEY ("id"));
CREATE TABLE "BookQuestion" ("id" TEXT NOT NULL,"bookId" TEXT NOT NULL,"chapterId" TEXT NOT NULL,"questionType" TEXT NOT NULL,"questionText" TEXT NOT NULL,"options" JSONB,"correctAnswer" TEXT,"explanation" TEXT,"marks" INTEGER NOT NULL DEFAULT 1,"difficulty" TEXT NOT NULL DEFAULT 'MEDIUM',"bloomLevel" TEXT,"competency" TEXT,"approved" BOOLEAN NOT NULL DEFAULT false,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "BookQuestion_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ChapterLearningOutcome" ("id" TEXT NOT NULL,"chapterId" TEXT NOT NULL,"outcome" TEXT NOT NULL,"bloomLevel" TEXT,"competency" TEXT,"sortOrder" INTEGER NOT NULL DEFAULT 0,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "ChapterLearningOutcome_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ChapterActivity" ("id" TEXT NOT NULL,"chapterId" TEXT NOT NULL,"title" TEXT NOT NULL,"objective" TEXT NOT NULL,"materials" TEXT,"durationMinutes" INTEGER,"groupType" TEXT,"instructions" TEXT NOT NULL,"expectedLearning" TEXT,"assessment" TEXT,"safetyNotes" TEXT,"approved" BOOLEAN NOT NULL DEFAULT false,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "ChapterActivity_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "BookChapter_bookId_chapterNumber_key" ON "BookChapter"("bookId","chapterNumber");CREATE UNIQUE INDEX "BookChapter_bookId_slug_key" ON "BookChapter"("bookId","slug");CREATE INDEX "BookChapter_bookId_sortOrder_idx" ON "BookChapter"("bookId","sortOrder");CREATE INDEX "BookQuestion_bookId_chapterId_idx" ON "BookQuestion"("bookId","chapterId");CREATE INDEX "BookQuestion_questionType_difficulty_approved_idx" ON "BookQuestion"("questionType","difficulty","approved");CREATE INDEX "ChapterLearningOutcome_chapterId_sortOrder_idx" ON "ChapterLearningOutcome"("chapterId","sortOrder");CREATE INDEX "ChapterActivity_chapterId_approved_idx" ON "ChapterActivity"("chapterId","approved");
ALTER TABLE "BookChapter" ADD CONSTRAINT "BookChapter_bookId_fkey" FOREIGN KEY ("bookId") REFERENCES "Book"("id") ON DELETE CASCADE ON UPDATE CASCADE;ALTER TABLE "BookQuestion" ADD CONSTRAINT "BookQuestion_bookId_fkey" FOREIGN KEY ("bookId") REFERENCES "Book"("id") ON DELETE CASCADE ON UPDATE CASCADE;ALTER TABLE "BookQuestion" ADD CONSTRAINT "BookQuestion_chapterId_fkey" FOREIGN KEY ("chapterId") REFERENCES "BookChapter"("id") ON DELETE RESTRICT ON UPDATE CASCADE;ALTER TABLE "ChapterLearningOutcome" ADD CONSTRAINT "ChapterLearningOutcome_chapterId_fkey" FOREIGN KEY ("chapterId") REFERENCES "BookChapter"("id") ON DELETE RESTRICT ON UPDATE CASCADE;ALTER TABLE "ChapterActivity" ADD CONSTRAINT "ChapterActivity_chapterId_fkey" FOREIGN KEY ("chapterId") REFERENCES "BookChapter"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
